// 'afterbegin': Bên trong, ở đầu
// 'beforeend': Bên trong, ở cuối  
// 'afterend': Sau element</code></pre><h3 style="-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(37, 99, 235);font-family:&quot;Be Vietnam Pro&quot;, sans-serif;font-size:1.5rem;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;letter-spacing:normal;line-height:1.3;margin:2.5rem 0px 1.5rem;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;"><strong>4.2. Xóa Và Thay Thế Phần Tử</strong></h3><pre style="-webkit-text-stroke-width:0px;background-color:rgb(15, 23, 42);border-left:4px solid rgb(245, 158, 11);border-radius:12px;box-sizing:border-box;color:rgb(15, 23, 42);cursor:pointer;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:2rem 0px;orphans:2;overflow-x:auto;padding:1.5rem;position:relative;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;widows:2;word-spacing:0px;"><code class="language-javascript" style="box-sizing:border-box;color:rgb(226, 232, 240);font-family:&quot;Courier New&quot;, monospace;font-size:0.95rem;margin:0px;padding:0px;">const element = document.querySelector('#toRemove');
